# Check girth: find shortest cycle
from collections import defaultdict, deque
n = 19
adj = defaultdict(set)
for u,v in edges:
    adj[u].add(v); adj[v].add(u)

def girth(n, adj):
    g = float('inf')
    for s in range(n):
        dist = {s:0}; parent = {s:-1}
        q = deque([s])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u]+1; parent[v]=u
                    q.append(v)
                elif parent[u] != v:
                    c = dist[u]+dist[v]+1
                    if c < g: g = c
    return g

print("girth:", girth(n, adj))

# Check bipartite => 2-colorable
color = {}
for s in range(n):
    if s not in color:
        color[s]=0
        q=deque([s])
        while q:
            u=q.popleft()
            for v in adj[u]:
                if v not in color:
                    color[v]=1-color[u]; q.append(v)
                elif color[v]==color[u]:
                    print("not bipartite"); break
print("bipartite OK")
